#!/usr/bin/env node
// Generates knowledge/wiki/index.md from the front matter of every wiki article.
// The index is an aggregate that every story PR would otherwise edit by hand; generated
// and sorted, parallel PRs touch different lines and a conflict is fixed by regenerating.
//
// Usage: node .github/scripts/wiki-index.mjs [--check] [--root <wiki dir>]
//   --check  exit 1 if index.md differs from the generated text (CI)
//
// Front matter of an article (first lines of the file):
//   ---
//   summary: One line that lets an agent decide whether to read the article.
//   concepts:
//     - name: Session
//       code: api/src/auth.ts, api/src/authStores.ts
//       relates: identifies Account; is required by API access protection
//     - name: Item
//       status: planned
//   ---
// "relates" is a list of "<label> <Concept>" separated by ";", where <Concept> is the
// name of a concept defined in any article.
import { readFileSync, writeFileSync, readdirSync, statSync } from 'node:fs';
import { join, relative } from 'node:path';

const TOPICS = [
  ['product', 'Product concepts and features: purpose, rules, status, relations.'],
  ['architecture', 'How the software is built: system, data model, API, auth, deploy.'],
  ['design', 'Design concepts, UI patterns, screens; assets in `design/assets/`.'],
  ['decisions', 'One record per product or technical decision, named after the decision.'],
  ['users', 'Who uses the app and what they need.'],
  ['process', 'How work moves through the software factory.'],
  ['lessons', 'What the project learned and why its rules exist.'],
];

const args = process.argv.slice(2);
const check = args.includes('--check');
const rootIdx = args.indexOf('--root');
const root = rootIdx >= 0 ? args[rootIdx + 1] : 'knowledge/wiki';
const errors = [];

function walk(dir) {
  return readdirSync(dir).flatMap((f) => {
    const p = join(dir, f);
    return statSync(p).isDirectory() ? walk(p) : p.endsWith('.md') ? [p] : [];
  });
}

function parse(path) {
  const rel = relative(root, path).split('\\').join('/');
  const text = readFileSync(path, 'utf8');
  const fm = text.match(/^---\n([\s\S]*?)\n---\n/);
  if (!fm) { errors.push(`${rel}: no front matter (--- summary: ... ---) at the top`); return null; }
  const meta = { summary: '', concepts: [] };
  let current = null;
  for (const line of fm[1].split('\n')) {
    let m;
    if ((m = line.match(/^\s*-\s+name:\s*(.+)$/))) { current = { name: m[1].trim(), article: rel }; meta.concepts.push(current); }
    else if ((m = line.match(/^\s+(code|status|relates):\s*(.*)$/)) && current) current[m[1]] = m[2].trim();
    else if ((m = line.match(/^summary:\s*(.+)$/))) meta.summary = m[1].trim();
    else if (/^concepts:\s*$/.test(line) || line.trim() === '') continue;
    else errors.push(`${rel}: front matter line not understood: "${line}"`);
  }
  const h1 = text.slice(fm[0].length).match(/^# (.+)$/m);
  if (!meta.summary) errors.push(`${rel}: front matter has no summary`);
  if (!h1) errors.push(`${rel}: no "# Title" line`);
  return { rel, topic: rel.split('/')[0], title: h1 ? h1[1].trim() : rel, ...meta };
}

const articles = walk(root).filter((p) => relative(root, p) !== 'index.md').map(parse).filter(Boolean);
const topicNames = TOPICS.map(([t]) => t);
for (const a of articles) {
  if (!topicNames.includes(a.topic) || !a.rel.includes('/')) errors.push(`${a.rel}: not in a known topic folder (${topicNames.join(', ')})`);
}

const concepts = new Map();
for (const c of articles.flatMap((a) => a.concepts)) {
  if (concepts.has(c.name)) errors.push(`concept "${c.name}" is defined twice (${concepts.get(c.name).article}, ${c.article})`);
  concepts.set(c.name, c);
}
const names = [...concepts.keys()].sort((a, b) => b.length - a.length); // longest first: "Account deletion" before "Account"
const edges = [];
for (const c of concepts.values()) {
  for (const clause of (c.relates || '').split(';').map((s) => s.trim()).filter(Boolean)) {
    const to = names.find((n) => clause.endsWith(' ' + n));
    if (!to) { errors.push(`${c.article}: concept "${c.name}" relates to an unknown concept: "${clause}"`); continue; }
    edges.push({ from: c.name, label: clause.slice(0, -to.length).trim(), to });
  }
}

if (errors.length) {
  for (const e of errors) process.stdout.write(`FAIL wiki-index: ${e}\n`);
  process.exit(1);
}

const byName = (a, b) => a.localeCompare(b, 'en', { sensitivity: 'base' });
const id = (n) => n.replace(/[^A-Za-z0-9]/g, '');
const planned = (n) => concepts.get(n).status === 'planned';
const out = [];
out.push('# Knowledge Base Index', '');
out.push('<!-- Generated by .github/scripts/wiki-index.mjs from the front matter of each article. Do not edit by hand: run `npm run wiki:index`. On a merge conflict, take either side and regenerate. -->', '');
out.push('Start here, every time, before you plan, build or review. Read this page in full, then every article that is relevant to your task. Maintained by agents with every change, per `.agents/skills/wiki/SKILL.md` ([how project knowledge is managed](process/project-knowledge.md)).', '');
out.push('## Concept map', '');
out.push('Solid boxes exist in the code; dashed boxes are planned and have no code yet.', '');
out.push('```mermaid', 'graph LR');
for (const n of [...concepts.keys()].sort(byName)) out.push(`  ${id(n)}["${n.replace(/"/g, "'")}"]`);
for (const e of [...edges].sort((a, b) => byName(a.from, b.from) || byName(a.to, b.to) || byName(a.label, b.label))) {
  const arrow = planned(e.from) || planned(e.to) ? '-.->' : '-->';
  out.push(`  ${id(e.from)} ${arrow}|${e.label.replace(/[|"]/g, ' ')}| ${id(e.to)}`);
}
for (const n of [...concepts.keys()].sort(byName).filter(planned)) out.push(`  class ${id(n)} planned`);
out.push('  classDef planned stroke-dasharray: 5 5', '```', '');
out.push('| Concept | Article | Code entry point | Related to |', '|---------|---------|------------------|------------|');
for (const n of [...concepts.keys()].sort(byName)) {
  const c = concepts.get(n);
  const art = articles.find((a) => a.rel === c.article);
  const related = [...new Set(edges.flatMap((e) => (e.from === n ? [e.to] : e.to === n ? [e.from] : [])))].sort(byName);
  const code = c.code && c.code !== 'none' ? c.code.split(',').map((s) => '`' + s.trim() + '`').join(', ') : 'none';
  out.push(`| ${n}${planned(n) ? ' (planned)' : ''} | [${art.title}](${c.article}) | ${code}${planned(n) ? ' (planned)' : ''} | ${related.join(', ') || 'none'} |`);
}
out.push('', '## Articles by topic');
for (const [topic, desc] of TOPICS) {
  out.push('', `## ${topic}`, '', desc, '');
  const list = articles.filter((a) => a.topic === topic).sort((a, b) => byName(a.title, b.title));
  if (!list.length) { out.push('No articles yet.'); continue; }
  out.push('| Article | Summary |', '|---------|---------|');
  for (const a of list) out.push(`| [${a.title}](${a.rel}) | ${a.summary.replace(/\|/g, '\\|')} |`);
}
const text = out.join('\n') + '\n';
const indexPath = join(root, 'index.md');
if (check) {
  let current = '';
  try { current = readFileSync(indexPath, 'utf8'); } catch { /* missing index counts as stale */ }
  if (current !== text) {
    process.stdout.write('FAIL wiki-index: knowledge/wiki/index.md is not up to date with the article front matter. Run `npm run wiki:index` and commit the result; never edit index.md by hand.\n');
    process.exit(1);
  }
  process.stdout.write('wiki-index: ok\n');
} else {
  writeFileSync(indexPath, text);
  process.stdout.write(`wiki-index: wrote ${indexPath} (${articles.length} articles, ${concepts.size} concepts)\n`);
}
